-- =====================================================================
--  MI COMISARÍA - Datos oficiales de dependencias (SIGETec, actualizado 26/10/2026)
--  Nombre oficial, distrito, sector y TELÉFONOS de cada dependencia.
--  Los teléfonos son internos (Red WIN, jefes, guardia): por eso viven acá, en la base,
--  y NO en archivos públicos. Solo el personal logueado puede leerlos.
--
--  CÓMO USARLO (Supabase > SQL Editor > New query): pegá todo y apretá Run.
--  Es seguro ejecutarlo más de una vez (actualiza las filas existentes).
--  "clave" = el nombre exacto que guarda el sistema en solicitudes.comisaria_asignada.
-- =====================================================================
create table if not exists public.dependencias_contacto (
  clave       text primary key,
  nombre      text not null,
  tipo        text,
  distrito    int,
  sector      int,
  telefonos   jsonb not null default '[]'::jsonb,
  actualizado date default '2026-10-26'
);
alter table public.dependencias_contacto enable row level security;
revoke all on public.dependencias_contacto from anon, authenticated;
grant select on public.dependencias_contacto to authenticated;
drop policy if exists "Personal logueado ve contactos" on public.dependencias_contacto;
create policy "Personal logueado ve contactos"
on public.dependencias_contacto for select to authenticated using (true);

on conflict (clave) do update
  set nombre = excluded.nombre, tipo = excluded.tipo, distrito = excluded.distrito,
      sector = excluded.sector, telefonos = excluded.telefonos, actualizado = '2026-10-26';
